connection.onDidChangeTextDocument((p) => {
  const text = documents.get(p.textDocument.uri).getText();
  const diags = [];
  try {
    parse(tokenize(text));                    // 이미 만든 파서
  } catch (e) {
    diags.push({
      range: { start: pos(e.at), end: pos(e.at + 1) },   // 토큰 위치가 여기서 값을 한다
      message: e.message,
      severity: 1,                                        // Error
    });
  }
  connection.sendDiagnostics({ uri: p.textDocument.uri, diagnostics: diags });
});
